"""Regenerate the synthesizable constant angle tables (Python standard library)."""
import math
from pathlib import Path

destination = Path(__file__).resolve().parents[1] / "FDP2026.srcs/sources_1/new/Ray_Tables.vh"
lines = [
    "// Generated by tests/generate_ray_tables.py; no run-time trig/division.",
    "// No include guard: functions are local to each including module.",
    "function [7:0] quarter_sine;",
    "    input [8:0] phase;",
    "    begin",
    "        case (phase)",
]
for phase in range(257):
    value = math.floor(128 * math.sin(phase * math.pi / 512) + 0.5)
    lines.append(f"            9'd{phase}: quarter_sine = 8'd{value};")
lines += [
    "            default: quarter_sine = 8'd0;",
    "        endcase",
    "    end",
    "endfunction",
    "function signed [8:0] sine_step;",
    "    input [9:0] phase;",
    "    reg [8:0] folded;",
    "    reg signed [8:0] magnitude;",
    "    begin",
    "        folded = phase[8] ? (9'd256 - {1'b0,phase[7:0]}) : {1'b0,phase[7:0]};",
    "        magnitude = $signed({1'b0,quarter_sine(folded)});",
    "        sine_step = phase[9] ? -magnitude : magnitude;",
    "    end",
    "endfunction",
    "// 96 angular samples spanning -85..+85 units (~59.77 degree FOV).",
    "function [9:0] column_offset;",
    "    input [6:0] column;",
    "    begin",
    "        case (column)",
]
for column in range(96):
    offset = (170 * column + 47) // 95 - 85
    lines.append(f"            7'd{column}: column_offset = 10'd{offset % 1024};")
lines += [
    "            default: column_offset = 10'd0;",
    "        endcase",
    "    end",
    "endfunction",
]
destination.write_text("\n".join(lines) + "\n", encoding="ascii")
print(f"Generated {destination.name}")
